export interface ProductState {
  productId: string;
  version: string;
  records: {
    version: 1;
    /** @minLength 1 */
    productId: string;
    /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
    id: string;
    /**
     * Читаемый ключ сущности; назначается ядром, может иметь прежние алиасы
     * @minLength 1
     * @maxLength 128
     * @pattern ^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)*$
     */
    key?: string;
    reservedKeys?: string[];
    /**
     * @exclusiveMin 0
     * @max 9007199254740991
     */
    revision: number;
    fields:
      | {
          kind: "passport";
          /**
           * Однострочное название
           * @minLength 1
           */
          name: string;
          /** Краткое многострочное описание обычным текстом */
          summary: string;
          /** Полное описание в Markdown */
          description: string;
        }
      | {
          kind: "feature";
          /**
           * Однострочное название
           * @minLength 1
           */
          name: string;
          /** Краткое многострочное описание обычным текстом */
          summary: string;
          /** Полное описание в Markdown */
          description: string;
        }
      | {
          kind: "scenario";
          /**
           * Постоянный ID родительской фичи
           * @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$
           */
          featureId: string;
          /**
           * Однострочное название сценария
           * @minLength 1
           */
          name: string;
          /** Описание поведения сценария в Markdown */
          description: string;
        }
      | {
          kind: "application";
          /**
           * Однострочное название
           * @minLength 1
           */
          name: string;
          /** Краткое многострочное описание обычным текстом */
          summary: string;
          /** Полное описание в Markdown */
          description: string;
          /**
           * Неизменяемый уникальный адрес приложения и доски: 1–64 символа, строчные латинские буквы, цифры и дефисы; product, infrastructure и new зарезервированы
           * @minLength 1
           * @maxLength 64
           * @pattern ^[a-z0-9]+(?:-[a-z0-9]+)*$
           */
          slug: string;
          /**
           * Префикс задач доски; при создании по умолчанию из slug, затем неизменяем
           * @pattern ^[A-Z][A-Z0-9]{1,15}$
           */
          prefix?: string;
          /** Назначение приложения: клиентское, серверное или внутреннее */
          type: ProductStateTypeEnum;
        }
      | {
          kind: "scope";
          /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
          applicationId: string;
          /** @maxItems 10000 */
          contracts: {
            /**
             * Постоянный ID общей фичи
             * @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$
             */
            featureId: string;
            /** Постоянный ID сценария; null для общего вклада в фичу */
            scenarioId: string | null;
            /**
             * Однострочное название реализации
             * @minLength 1
             */
            title: string;
            /** Описание вклада приложения в Markdown */
            description: string;
            /** Состояние вклада приложения */
            status: ProductStateStatusEnum;
            /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
            id: string;
            /**
             * Читаемый ключ сущности; назначается ядром, может иметь прежние алиасы
             * @minLength 1
             * @maxLength 128
             * @pattern ^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)*$
             */
            key?: string;
            /**
             * @exclusiveMin 0
             * @max 9007199254740991
             */
            revision?: number;
            active: boolean;
            basis: string;
          }[];
        }
      | {
          kind: "document";
          /**
           * Однострочное название документа
           * @minLength 1
           */
          name: string;
          /** Краткое обычное описание документа */
          summary: string;
          /** Полный текст документа в Markdown */
          body: string;
          /** Тип: ТЗ, описание, правила, инструкция, проект решения, решение или исследование */
          documentKind: ProductStateDocumentKindEnum;
          /** Раздел; null — без раздела */
          sectionId?: string | null;
          /** Состояние публикации: черновик, действующий или архив; не подтверждает истинность текста */
          documentStatus?: ProductStateDocumentStatusEnum;
          /** Закреплён для всех участников проекта */
          pinned?: boolean;
          /**
           * Адресные связи документа; текст и связи сохраняются атомарно
           * @maxItems 100
           */
          relations?: {
            /** Связанная сущность проекта: вид и постоянный ID */
            target: {
              /** Вид связанной сущности проекта */
              kind: ProductStateKindEnum;
              /**
               * Постоянный ID связанной сущности
               * @pattern ^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$
               */
              id: string;
            };
            /** references — контекст для сущности; documents — документ описывает сущность */
            type: ProductStateTypeEnum1;
            /** Когда и зачем читать документ: необязательное пояснение Markdown */
            description: string;
          }[];
          /**
           * Явные области применимости документа по постоянным ID
           * @maxItems 1000
           */
          links: (
            | {
                kind: "product";
              }
            | {
                kind: "feature";
                /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
                id: string;
              }
            | {
                kind: "scenario";
                /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
                id: string;
              }
            | {
                kind: "application";
                /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
                id: string;
              }
            | {
                kind: "implementation";
                /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
                applicationId: string;
                /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
                id: string;
              }
          )[];
        };
    /**
     * Момент времени в UTC
     * @format date-time
     * @pattern ^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z))$
     */
    createdAt: string;
    /**
     * Момент времени в UTC
     * @format date-time
     * @pattern ^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z))$
     */
    updatedAt: string;
    /**
     * Автор операции
     * @maxLength 128
     */
    createdBy: string;
    /**
     * Автор операции
     * @maxLength 128
     */
    updatedBy: string;
  }[];
  readiness: {
    /** @pattern ^(?:[A-Za-z0-9]{8}|passport|(?:feature|scenario|application|scope|document|contract)_[a-f0-9]{32})$ */
    id: string;
    status: ProductStateStatusEnum1;
    /**
     * @min 0
     * @max 9007199254740991
     */
    participants: number;
    /**
     * @min 0
     * @max 9007199254740991
     */
    completed: number;
    /**
     * @min 0
     * @max 9007199254740991
     */
    stale: number;
  }[];
}

